const input=$json;
const reason=String(input.reason_code ?? '').trim().toUpperCase();
const canonicalLockReasons=new Set([
  'FINANCIAL','LEGAL','COMPLAINT','BARGAIN','EXTRA_DISCOUNT',
  'CUSTOMER_PRICE_PROPOSAL','NON_STANDARD_POST_CONTRACT_CHANGE',
  'LOCALITY_NO_RULE','CRITICAL_FACT_CONFLICT','SPECIAL_OPERATION',
  'PAYMENT_DIVERGENCE','ADDON_PRICE_MISSING'
]);
const forceLock=Boolean(input.force_lock);
const lockRequired=forceLock || canonicalLockReasons.has(reason);
const operations=[];

if(lockRequired && !input.human_lock){
  operations.push({action:'ENABLE_HUMAN_LOCK',reason_code:reason || 'HUMAN_REQUIRED'});
}
operations.push({action:'CREATE_HUMAN_TASK',reason_code:reason || 'HUMAN_REQUIRED'});
if(lockRequired){
  operations.push({action:'CANCEL_AUTOMATIC_FOLLOWUPS',reason_code:'HUMAN_LOCK'});
}

return {json:{
  contract_version:'1.0.0',
  status:'human_required',
  customer_event_id:input.customer_event_id ?? null,
  reason_code:reason || 'HUMAN_REQUIRED',
  lock_required:lockRequired,
  operations,
  customer_message_action:{action:'COMPOSE_HANDOFF_ACK'},
  blockers:[]
}};
